mapper.select:
select a.*, idm.name product_name, idt.name product_type_name, idm.device_type from iot_device a
    left join iot_product_type idt on a.product_type_id=idt.id
    left join iot_product idm on a.product_id=idm.id
    left join iot_device_group dg on a.device_group_id=dg.id


        and a.status = #{entity.status}


        and idt.alias = #{entity.alias}


        and idm.name like '%${entity.productName}%'


        and a.product_id = #{entity.productId}


        and a.device_group_id = #{entity.deviceGroupId}


        and a.product_type_id = #{entity.productTypeId}


        and a.device_sn like '%${entity.deviceSn}%'


        and a.name like '%${entity.name}%'


order by a.create_time desc

select a.* from iot_device a
    left join iot_product ip on a.product_id=ip.id
where ip.device_type='Gateway' and ip.gateway_id=#{gatewayId}

select a.uid, a.device_group_id groupId, p.device_type type, a.status, a.device_sn deviceSn
    , pd.device_sn parentDeviceSn, p.code productCode, pl.code protocolCode, a.status
from iot_device a
    inner join iot_device pd on a.pid = pd.id
    inner join iot_product p on a.product_id = p.id
    inner join iot_protocol pl on p.protocol_code = pl.code
where pl.code=#{protocolCode}

    and pd.device_sn = #{parentDeviceSn}

and a.device_sn in (

    #{deviceSn}
)
